import{_ as s,o as a,c as t,a4 as r}from"./chunks/framework.BUqnS5H7.js";const h=JSON.parse('{"title":"进程与内存架构","description":"","frontmatter":{"doc_id":"pg-process-memory","title":"进程与内存架构"},"headers":[],"relativePath":"postgresql/02-architecture/chapter-01-process-memory.md","filePath":"postgresql/02-architecture/chapter-01-process-memory.md"}'),c={name:"postgresql/02-architecture/chapter-01-process-memory.md"};function n(l,e,o,p,i,d){return a(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="进程与内存架构" tabindex="-1" data-src-line="2" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">进程与内存架构 <a class="header-anchor" href="#进程与内存架构" aria-label="Permalink to &quot;进程与内存架构&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><p data-src-line="4" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">一条查询卡住，<code>top</code> 一看满屏几十个 <code>postgres</code> 进程在抢 CPU。这不是 bug，是 PG 的进程模型——每个连接一个进程。要理解为什么会这样、怎么避免，得先看清进程和内存这两层结构。</p></blockquote><h2 id="_1-多进程架构总览" tabindex="-1" data-src-line="6" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">1. 多进程架构总览 <a class="header-anchor" href="#_1-多进程架构总览" aria-label="Permalink to &quot;1. 多进程架构总览&quot;">​</a></h2><p data-src-line="8" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">PostgreSQL 采用经典的 <strong>一连接一进程（process-per-connection）</strong> 模型。每当客户端发起连接，Postmaster 会 fork 出一个独立的 Backend Process 来服务该连接。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   PostgreSQL 集群                      │</span></span>
<span class="line"><span>│                                                       │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────────┐    │</span></span>
<span class="line"><span>│  │              Postmaster (主进程)               │    │</span></span>
<span class="line"><span>│  │   监听端口 → 接收连接 → fork Backend Process     │    │</span></span>
<span class="line"><span>│  └──────┬────────┬────────┬────────┬─────────────┘    │</span></span>
<span class="line"><span>│         │        │        │        │                  │</span></span>
<span class="line"><span>│    ┌────▼──┐┌────▼──┐┌────▼──┐┌────▼──┐               │</span></span>
<span class="line"><span>│    │Backend││Backend││Backend││Backend│  ← 客户端连接   │</span></span>
<span class="line"><span>│    │  P1   ││  P2   ││  P3   ││  P4   │               │</span></span>
<span class="line"><span>│    └───────┘└───────┘└───────┘└───────┘               │</span></span>
<span class="line"><span>│                                                       │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────────┐    │</span></span>
<span class="line"><span>│  │            Background Workers（后台进程）       │    │</span></span>
<span class="line"><span>│  │  ┌──────────┐ ┌──────────┐ ┌───────────────┐  │    │</span></span>
<span class="line"><span>│  │  │WAL Writer│ │Bg Writer │ │Checkpointer   │  │    │</span></span>
<span class="line"><span>│  │  └──────────┘ └──────────┘ └───────────────┘  │    │</span></span>
<span class="line"><span>│  │  ┌──────────┐ ┌──────────┐ ┌───────────────┐  │    │</span></span>
<span class="line"><span>│  │  │Autovacuum│ │Stats     │ │WAL Archiver   │  │    │</span></span>
<span class="line"><span>│  │  │Launcher  │ │Collector │ │(可选)          │  │    │</span></span>
<span class="line"><span>│  │  └──────────┘ └──────────┘ └───────────────┘  │    │</span></span>
<span class="line"><span>│  └───────────────────────────────────────────────┘    │</span></span>
<span class="line"><span>│                                                       │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────────┐    │</span></span>
<span class="line"><span>│  │               共享内存 (Shared Memory)         │    │</span></span>
<span class="line"><span>│  │  Shared Buffers | WAL Buffers | CLOG | ...    │    │</span></span>
<span class="line"><span>│  └───────────────────────────────────────────────┘    │</span></span>
<span class="line"><span>└───────────────────────────────────────────────────────┘</span></span></code></pre></div><p data-src-line="42" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>为什么选多进程，而不是像 MySQL 那样用多线程？</strong></p><p data-src-line="44" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>好处：隔离性与可移植性</strong></p><ul data-src-line="46" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><li data-src-line="46" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>一个 Backend 崩溃不连累其他连接</strong>。每个 Backend 有独立地址空间，一个进程踩了野指针、段错误，操作系统直接杀掉它，其余连接照常服务。多线程模型下，一个线程的缓冲区溢出会写坏共享堆，殃及整个实例。</li><li data-src-line="47" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>可移植性</strong>。PostgreSQL 的前身 POSTGRES 诞生于 1986 年，那个年代 Unix 线程库远未成熟，各系统线程行为不一致；而 <code>fork()</code> 是 Unix 基石，所有平台都稳定。选进程，PG 就不依赖任何特定线程实现，能跑在所有类 Unix 系统上。</li></ul><p data-src-line="49" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>弊端：单连接贵，高并发必须靠连接池</strong></p><ul data-src-line="51" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><li data-src-line="51" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>fork 开销大</strong>。每次新连接要 fork 进程、复制地址空间，单连接内存可达几 MB 到十几 MB，而一个线程只需几百 KB。</li><li data-src-line="52" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>上下文切换慢</strong>。进程切换要刷新 TLB、切换页表，比线程切换贵得多。</li><li data-src-line="53" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>连接数受限</strong>。几千个连接就是几千个进程，内存和 CPU 都扛不住。</li></ul><p data-src-line="55" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">一句话：PG 用进程换来<strong>隔离性和可移植性</strong>，代价是<strong>单连接贵</strong>，于是把高并发压力转移给连接池去扛（见 §5）。</p><h2 id="_2-后台进程-为-backend-分担落盘与维护工作" tabindex="-1" data-src-line="57" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">2. 后台进程：为 Backend 分担落盘与维护工作 <a class="header-anchor" href="#_2-后台进程-为-backend-分担落盘与维护工作" aria-label="Permalink to &quot;2. 后台进程：为 Backend 分担落盘与维护工作&quot;">​</a></h2><p data-src-line="59" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">Backend Process 只负责执行 SQL，落盘、维护这类工作交给后台进程。它们按重要性分三层：Checkpointer 和 WAL Writer 决定数据安全，Background Writer 摊平 IO 峰值，Autovacuum 防表膨胀（机制另文讲）、Stats Collector 供优化器估算成本（知道存在即可）。</p><h3 id="_2-1-checkpointer-与-background-writer-一个是保障-一个是缓冲" tabindex="-1" data-src-line="61" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">2.1 Checkpointer 与 Background Writer：一个是保障，一个是缓冲 <a class="header-anchor" href="#_2-1-checkpointer-与-background-writer-一个是保障-一个是缓冲" aria-label="Permalink to &quot;2.1 Checkpointer 与 Background Writer：一个是保障，一个是缓冲&quot;">​</a></h3><p data-src-line="63" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">这俩最容易混。一句话区分：</p><ul data-src-line="65" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><li data-src-line="65" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>Checkpointer 对数据安全负责</strong>：执行 Checkpoint，把某个时间点之前所有脏页刷盘，再更新控制文件，标记&quot;到这里为止的 WAL 可以回收&quot;。</li><li data-src-line="66" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>Background Writer 只负责摊平 IO</strong>：平时把部分脏页提前刷出去，让 Checkpoint 那一刻不至于瞬间写爆磁盘。它刷不刷、刷多少，不影响数据安全。</li></ul><p data-src-line="68" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">为什么需要两个？Checkpoint 必须&quot;一次性把所有脏页落盘&quot;，如果没人提前刷，Checkpoint 那一刻磁盘 IO 瞬间打满，所有查询变慢。Background Writer 就是那个平时悄悄刷一点的进程，把峰值摊平。</p><p data-src-line="70" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">Checkpoint 触发条件：<code>checkpoint_timeout</code>（默认 5min）或 WAL 累积到 <code>max_wal_size</code>。</p><h3 id="_2-2-wal-writer-提交成功-数据已落盘" tabindex="-1" data-src-line="72" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">2.2 WAL Writer：提交成功 ≠ 数据已落盘 <a class="header-anchor" href="#_2-2-wal-writer-提交成功-数据已落盘" aria-label="Permalink to &quot;2.2 WAL Writer：提交成功 ≠ 数据已落盘&quot;">​</a></h3><p data-src-line="74" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><code>COMMIT</code> 返回成功前，这条事务的 WAL 必须刷到磁盘，否则崩溃后就丢了——这是 WAL 的立身之本。</p><p data-src-line="76" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">但 WAL 不是每条直接写盘：先写进共享内存的 WAL Buffer，再由 WAL Writer 刷到 WAL 段文件。<strong>同步提交</strong>（默认）时，<code>COMMIT</code> 主动触发刷盘；<code>synchronous_commit = off</code> 时交给 WAL Writer 按 <code>wal_writer_delay</code>（默认 200ms）周期刷，最多丢最近 200ms 的已提交事务。</p><blockquote data-src-line="78" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><p data-src-line="78" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>为什么不逐条写盘？</strong> 磁盘写入的最小单位是页（一般 8KB），而一条 WAL 记录往往只有几十字节，逐条写会把磁盘 IO 放大几十倍。先攒进 WAL Buffer，再由 WAL Writer 批量刷盘，能把零碎小写合并成连续大写。代价正是上面说的：异步提交时，<code>wal_writer_delay</code> 窗口内的已提交事务可能随宕机一起丢失——这是「IO 效率」换「持久性」的取舍。</p></blockquote><h3 id="_2-3-autovacuum-launcher" tabindex="-1" data-src-line="80" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">2.3 Autovacuum Launcher <a class="header-anchor" href="#_2-3-autovacuum-launcher" aria-label="Permalink to &quot;2.3 Autovacuum Launcher&quot;">​</a></h3><p data-src-line="82" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">定期检查死元组数量，超阈值拉起 Autovacuum Worker 清理。机制见 <a href="./../01-pg-unique/chapter-04-vacuum.html">VACUUM 章节</a>，这里不重复。</p><h3 id="_2-4-stats-collector" tabindex="-1" data-src-line="84" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">2.4 Stats Collector <a class="header-anchor" href="#_2-4-stats-collector" aria-label="Permalink to &quot;2.4 Stats Collector&quot;">​</a></h3><p data-src-line="86" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">一句话：收集表的行数、页数、索引使用率，供优化器估算执行计划成本。不用调参。</p><h2 id="_3-共享内存-shared-memory" tabindex="-1" data-src-line="88" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">3. 共享内存（Shared Memory） <a class="header-anchor" href="#_3-共享内存-shared-memory" aria-label="Permalink to &quot;3. 共享内存（Shared Memory）&quot;">​</a></h2><p data-src-line="90" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">前面这些进程——Backend 和后台进程——都要读写同一批数据页和 WAL，于是需要一块大家都能访问的内存。PostgreSQL 启动时分配这块共享内存，所有进程共享。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              共享内存 (Shared Memory)       │</span></span>
<span class="line"><span>│                                            │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │         Shared Buffers               │  │</span></span>
<span class="line"><span>│  │   (数据页缓存，核心组件)                │  │</span></span>
<span class="line"><span>│  │   默认 128MB，生产建议 RAM 的 25%       │  │</span></span>
<span class="line"><span>│  └──────────────────────────────────────┘  │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │         WAL Buffers                  │  │</span></span>
<span class="line"><span>│  │   (WAL 日志缓冲区)                     │  │</span></span>
<span class="line"><span>│  │   默认 -1 (自动 ≈ 64MB 的 1/32)        │  │</span></span>
<span class="line"><span>│  └──────────────────────────────────────┘  │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │         CLOG (Commit Log)            │  │</span></span>
<span class="line"><span>│  │   (事务提交状态，2bit/事务)             │  │</span></span>
<span class="line"><span>│  └──────────────────────────────────────┘  │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │     Lock Tables / Proc Array         │  │</span></span>
<span class="line"><span>│  │   (锁信息、进程状态数组)                │  │</span></span>
<span class="line"><span>│  └──────────────────────────────────────┘  │</span></span>
<span class="line"><span>└────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="shared-buffers-核心机制" tabindex="-1" data-src-line="117" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">Shared Buffers 核心机制 <a class="header-anchor" href="#shared-buffers-核心机制" aria-label="Permalink to &quot;Shared Buffers 核心机制&quot;">​</a></h3><table tabindex="0"><thead data-src-line="119" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><tr data-src-line="119" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><th style="text-align:left;">概念</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="121" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><tr data-src-line="121" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>Buffer Tag</strong></td><td style="text-align:left;">每个缓冲区页的唯一标识（RelFileNode + ForkNumber + BlockNumber）</td></tr><tr data-src-line="122" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>Buffer Descriptor</strong></td><td style="text-align:left;">描述缓冲区状态：pin count、usage count、dirty flag</td></tr><tr data-src-line="123" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>Clock-Sweep 算法</strong></td><td style="text-align:left;">缓存替换策略，类似 LRU 的简化版本</td></tr></tbody></table><blockquote data-src-line="125" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><p data-src-line="125" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>为什么设 25%，而且不能贪多？</strong> 数据读取的真实路径是：磁盘 → OS Page Cache → Shared Buffers → Backend。<code>shared_buffers</code> 存一份，OS Page Cache 往往还存一份，这就是 double buffering。</p><p data-src-line="127" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">如果 <code>shared_buffers</code> 设到 80% 内存，OS Page Cache 被挤得只剩一点，从磁盘读进来的数据没地方放，频繁换页，反而更慢。PG 的设计就是把 OS Page Cache 当二级缓存，所以 <code>shared_buffers</code> 只拿 25%，大头留给 OS。</p></blockquote><h2 id="_4-本地内存-local-memory" tabindex="-1" data-src-line="129" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">4. 本地内存（Local Memory） <a class="header-anchor" href="#_4-本地内存-local-memory" aria-label="Permalink to &quot;4. 本地内存（Local Memory）&quot;">​</a></h2><p data-src-line="131" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">每个 Backend Process 独立分配的内存区域，连接结束时释放。</p><table tabindex="0"><thead data-src-line="133" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><tr data-src-line="133" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">用途</th></tr></thead><tbody data-src-line="135" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><tr data-src-line="135" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>work_mem</strong></td><td style="text-align:left;">4MB</td><td style="text-align:left;">排序（ORDER BY）、哈希连接（Hash Join）、哈希聚合使用的内存。<strong>每个操作</strong>独立分配，复杂查询可能分配多个</td></tr><tr data-src-line="136" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>maintenance_work_mem</strong></td><td style="text-align:left;">64MB</td><td style="text-align:left;">VACUUM、CREATE INDEX、ALTER TABLE ADD FK 等维护操作使用</td></tr><tr data-src-line="137" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>temp_buffers</strong></td><td style="text-align:left;">8MB</td><td style="text-align:left;">临时表（TEMP TABLE）的缓冲区</td></tr><tr data-src-line="138" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>hash_mem_multiplier</strong></td><td style="text-align:left;">1.0</td><td style="text-align:left;">Hash Join 可额外使用 work_mem 的倍数（PG 13+）</td></tr></tbody></table><blockquote data-src-line="140" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><p data-src-line="140" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong><code>work_mem</code> 是本地内存里最容易爆的坑。</strong> 它的单位不是&quot;每个连接&quot;，而是&quot;每个排序/哈希操作&quot;。一条 SQL 同时有 3 个排序、2 个 Hash Join，就要开 5 份；再乘并发连接数。</p><p data-src-line="142" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">举例：<code>work_mem = 64MB</code>，一个连接一条 SQL 用 4 个操作就是 256MB；200 个并发连接同时跑，峰值 <strong>50GB</strong>，直接 OOM。</p><p data-src-line="144" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">所以 <code>work_mem</code> 不能照内存大小随便给。判断公式：<code>work_mem × 单查询最大操作数 × 并发连接数 ≤ 可用内存</code>。生产从 4MB~64MB 起步，用 <code>EXPLAIN ANALYZE</code> 看排序是否落盘（<code>Sort Method: external</code>）再调大。</p></blockquote><p data-src-line="146" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">到这里，开头那条查询为什么卡住，答案齐了：连接数过多吃掉 CPU（§1），<code>work_mem</code> 乘数效应吃掉内存（本节）。</p><h2 id="_5-进程模型对比-postgresql-vs-mysql" tabindex="-1" data-src-line="148" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">5. 进程模型对比：PostgreSQL vs MySQL <a class="header-anchor" href="#_5-进程模型对比-postgresql-vs-mysql" aria-label="Permalink to &quot;5. 进程模型对比：PostgreSQL vs MySQL&quot;">​</a></h2><table tabindex="0"><thead data-src-line="150" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><tr data-src-line="150" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><th style="text-align:left;">维度</th><th style="text-align:left;">PostgreSQL</th><th style="text-align:left;">MySQL (InnoDB)</th></tr></thead><tbody data-src-line="152" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><tr data-src-line="152" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>并发模型</strong></td><td style="text-align:left;">多进程（process-per-connection）</td><td style="text-align:left;">多线程（thread-per-connection）</td></tr><tr data-src-line="153" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>单连接开销</strong></td><td style="text-align:left;">较大（fork 进程，独立地址空间）</td><td style="text-align:left;">较小（创建线程，共享地址空间）</td></tr><tr data-src-line="154" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>内存隔离</strong></td><td style="text-align:left;">进程级隔离，一个 Backend crash 不影响其他</td><td style="text-align:left;">线程共享内存，一个线程 bug 可能影响整个实例</td></tr><tr data-src-line="155" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>上下文切换</strong></td><td style="text-align:left;">进程切换开销大（TLB 刷新等）</td><td style="text-align:left;">线程切换开销小</td></tr><tr data-src-line="156" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>高并发扩展</strong></td><td style="text-align:left;">依赖连接池（PgBouncer）缓解</td><td style="text-align:left;">原生支持更高并发连接数</td></tr><tr data-src-line="157" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>故障隔离</strong></td><td style="text-align:left;">强（进程独立崩溃恢复）</td><td style="text-align:left;">弱（需整体恢复）</td></tr><tr data-src-line="158" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><td style="text-align:left;"><strong>共享内存</strong></td><td style="text-align:left;">显式管理（Shared Buffers）</td><td style="text-align:left;">InnoDB Buffer Pool（类似但实现不同）</td></tr></tbody></table><blockquote data-src-line="160" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><p data-src-line="160" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">选进程还是选线程的动机，§1 已经讲透。这里只剩一个增量：为什么 MySQL 选了线程？因为它的定位是 Web 高并发读，线程单连接开销小、切换快，正好契合；代价是隔离性弱。而 PG 的进程模型早定型十年，改造成本高，索性沿用。</p></blockquote><blockquote data-src-line="162" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><p data-src-line="162" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>Java 开发者注意：</strong> PG 的进程模型意味着直接开几千个连接会消耗大量内存和 CPU（fork 开销）。生产环境<strong>必须</strong>使用连接池（PgBouncer 或应用层 HikariCP），将连接数控制在 <code>CPU核心数 × 2 + 磁盘数</code> 的范围内。</p></blockquote><h2 id="_6-连接建立流程" tabindex="-1" data-src-line="164" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">6. 连接建立流程 <a class="header-anchor" href="#_6-连接建立流程" aria-label="Permalink to &quot;6. 连接建立流程&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                   Postmaster              Backend Process</span></span>
<span class="line"><span>  │                         │                         │</span></span>
<span class="line"><span>  │── TCP 三次握手 ────────→ │                         │</span></span>
<span class="line"><span>  │                         │                         │</span></span>
<span class="line"><span>  │── SSL 协商(可选) ──────→ │                         │</span></span>
<span class="line"><span>  │                         │                         │</span></span>
<span class="line"><span>  │── StartupMessage ──────→│                         │</span></span>
<span class="line"><span>  │   (user, database, ...) │                         │</span></span>
<span class="line"><span>  │                         │── fork() ──────────────→│</span></span>
<span class="line"><span>  │                         │                         │</span></span>
<span class="line"><span>  │                         │                    验证用户(pg_hba.conf)</span></span>
<span class="line"><span>  │                         │                    验证密码</span></span>
<span class="line"><span>  │                         │                    加载数据库配置</span></span>
<span class="line"><span>  │                         │                    分配 Backend 内存</span></span>
<span class="line"><span>  │                         │                         │</span></span>
<span class="line"><span>  │←──── AuthenticationOk ──│←────────────────────────│</span></span>
<span class="line"><span>  │                         │                         │</span></span>
<span class="line"><span>  │←── ReadyForQuery ───────│                         │</span></span>
<span class="line"><span>  │                         │                         │</span></span>
<span class="line"><span>  │── Query/Parse/Bind ─────────────────────────────→ │</span></span>
<span class="line"><span>  │                         │                     执行SQL</span></span>
<span class="line"><span>  │←── DataRow / CommandComplete ──────────────────── │</span></span></code></pre></div><h3 id="关键步骤说明" tabindex="-1" data-src-line="191" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md">关键步骤说明 <a class="header-anchor" href="#关键步骤说明" aria-label="Permalink to &quot;关键步骤说明&quot;">​</a></h3><ol data-src-line="193" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><li data-src-line="193" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>Postmaster 接收连接请求</strong>：监听 <code>listen_addresses</code> 和 <code>port</code>（默认 5432）</li><li data-src-line="194" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>pg_hba.conf 认证</strong>：根据客户端 IP、用户名、数据库名匹配认证方式（md5/scram-sha-256/trust 等）</li><li data-src-line="195" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>fork Backend Process</strong>：Postmaster 调用 <code>fork()</code> 创建子进程</li><li data-src-line="196" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>Backend 初始化</strong>：加载 <code>postgresql.conf</code> 配置、设置信号处理、分配本地内存</li><li data-src-line="197" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>进入查询循环</strong>：Backend 等待客户端消息（Query/Parse/Bind/Execute），处理后返回结果</li></ol><blockquote data-src-line="199" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><p data-src-line="199" data-src-file="postgresql/02-architecture/chapter-01-process-memory.md"><strong>调优要点：</strong> 如果连接建立耗时过长，检查 <code>pg_hba.conf</code> 中是否使用了 DNS 解析（<code>host</code> vs <code>hostnossl</code>），以及 <code>max_connections</code> 是否已满。高并发场景建议前置 PgBouncer，使用 <strong>Transaction Pooling</strong> 模式复用连接。</p></blockquote>`,46)])])}const g=s(c,[["render",n]]);export{h as __pageData,g as default};
